//! Original bounded CPU level0 sampler and glTF metallic-roughness adaptation.
use serde::{Serialize,Deserialize};use super::{pbr::Material,vertex_stream::unit,lighting_stage::{Light,shade}};
#[derive(Clone,Copy,Debug,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum Wrap{Repeat,Mirror,Clamp}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Image{pub width:usize,pub height:usize,pub rgba8:Vec<u8>}
impl Image{pub fn validate(&self)->Result<(),String>{if self.width==0||self.height==0||self.width>4096||self.height>4096||self.width.checked_mul(self.height).and_then(|n|n.checked_mul(4))!=Some(self.rgba8.len()){return Err("image1..4096 exact RGBA8 required".into());}Ok(())}}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Slot{pub image:usize,pub wrap_s:Wrap,pub wrap_t:Wrap,pub linear:bool}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Surface{pub albedo:[f64;3],pub metallic:f64,pub roughness:f64,pub base:Option<Slot>,pub metal_rough:Option<Slot>,pub occlusion:Option<Slot>,pub normal:Option<Slot>,pub ao_strength:f64,pub normal_scale:f64,pub double_sided:bool}
fn linear(v:f64)->f64{if v<=0.04045{v/12.92}else{((v+0.055)/1.055).powf(2.4)}}
fn coord(i:i64,n:usize,w:Wrap)->usize{let n=n as i64;match w{Wrap::Repeat=>i.rem_euclid(n) as usize,Wrap::Clamp=>i.clamp(0,n-1) as usize,Wrap::Mirror=>{let j=i.rem_euclid(n*2);if j<n{j as usize}else{(2*n-1-j) as usize}}}}
/// UV origin top-left per glTF image rows; sRGB decoded before interpolation.
fn sample(slot:&Slot,images:&[Image],uv:[f64;2],srgb:bool)->Result<[f64;4],String>{if uv.iter().any(|v|!v.is_finite()||v.abs()>1e9){return Err("bounded finite UV required".into());}let im=images.get(slot.image).ok_or("texture image index missing")?;im.validate()?;let texel=|x:i64,y:i64|{let i=(coord(y,im.height,slot.wrap_t)*im.width+coord(x,im.width,slot.wrap_s))*4;std::array::from_fn::<_,4,_>(|j|{let v=im.rgba8[i+j] as f64/255.;if srgb&&j<3{linear(v)}else{v}})};let x=uv[0]*im.width as f64-0.5;let y=uv[1]*im.height as f64-0.5;if !slot.linear{return Ok(texel((x+0.5).floor() as i64,(y+0.5).floor() as i64));}let ix=x.floor() as i64;let iy=y.floor() as i64;let a=texel(ix,iy);let b=texel(ix+1,iy);let c=texel(ix,iy+1);let d=texel(ix+1,iy+1);let tx=x-x.floor();let ty=y-y.floor();Ok(std::array::from_fn(|j|(a[j]*(1.-tx)+b[j]*tx)*(1.-ty)+(c[j]*(1.-tx)+d[j]*tx)*ty))}
impl Surface{pub fn validate(&self,images:&[Image])->Result<(),String>{if images.len()>64||images.iter().try_fold(0usize,|a,i|a.checked_add(i.rgba8.len())).ok_or("texture aggregate overflow")?>64*1024*1024{return Err("max64 images /64MiB total decoded pixels".into());}for i in images{i.validate()?;}for slot in [&self.base,&self.metal_rough,&self.occlusion,&self.normal].into_iter().flatten(){if slot.image>=images.len(){return Err("texture image missing".into());}}if !self.ao_strength.is_finite()||!(0.0..=1.0).contains(&self.ao_strength)||!self.normal_scale.is_finite()||self.normal_scale.abs()>100.{return Err("AO strength0..1 normal scale abs<=100".into());}super::pbr::sample(&Material{albedo:self.albedo,metallic:self.metallic,roughness:self.roughness.max(0.001)},[0.,0.,1.],[0.,0.,1.],[0.,0.,1.])?;if !self.roughness.is_finite()||!(0.0..=1.0).contains(&self.roughness){return Err("roughness0..1".into());}Ok(())}
 pub fn evaluate(&self,images:&[Image],uv:[f64;2],n:[f64;3],t:[f64;4])->Result<(Material,[f64;3],f64),String>{let base=if let Some(s)=&self.base{sample(s,images,uv,true)?}else{[1.;4]};let mr=if let Some(s)=&self.metal_rough{sample(s,images,uv,false)?}else{[1.;4]};let ao=if let Some(s)=&self.occlusion{1.+self.ao_strength*(sample(s,images,uv,false)?[0]-1.)}else{1.};let n=unit(n)?;let tn=[t[0],t[1],t[2]];let dot=n.iter().zip(tn).map(|(a,b)|a*b).sum::<f64>();let tangent=unit(std::array::from_fn(|j|tn[j]-n[j]*dot))?;let bitangent=[n[1]*tangent[2]-n[2]*tangent[1],n[2]*tangent[0]-n[0]*tangent[2],n[0]*tangent[1]-n[1]*tangent[0]].map(|v|v*if t[3]<0.{-1.}else{1.});let normal=if let Some(s)=&self.normal{let p=sample(s,images,uv,false)?;let map=unit([(2.*p[0]-1.)*self.normal_scale,(2.*p[1]-1.)*self.normal_scale,2.*p[2]-1.])?;unit(std::array::from_fn(|j|tangent[j]*map[0]+bitangent[j]*map[1]+n[j]*map[2]))?}else{n};Ok((Material{albedo:std::array::from_fn(|j|self.albedo[j]*base[j]),metallic:self.metallic*mr[2],roughness:(self.roughness*mr[1]).max(0.001)},normal,ao))}
 /// AO only multiplies explicit diffuse ambient irradiance, never direct light/specular.
 /// PL1b: shade + per-light visibility (1=lit). All-lit is bit-identical to shade().
 pub fn shade_shadowed(&self,images:&[Image],uv:[f64;2],n:[f64;3],t:[f64;4],p:[f64;3],eye:[f64;3],lights:&[Light],ambient:[f64;3],vis:&[f64])->Result<[f64;3],String>{if ambient.iter().any(|v|!v.is_finite()||*v<0.||*v>1e9){return Err("bounded ambient irradiance required".into());}let(m,n,ao)=self.evaluate(images,uv,n,t)?;let direct=super::lighting_stage::shade_shadowed(&m,p,n,eye,lights,vis)?;Ok(std::array::from_fn(|j|direct[j]+ambient[j]*m.albedo[j]*(1.-m.metallic)*ao/std::f64::consts::PI))}
 pub fn shade(&self,images:&[Image],uv:[f64;2],n:[f64;3],t:[f64;4],p:[f64;3],eye:[f64;3],lights:&[Light],ambient:[f64;3])->Result<[f64;3],String>{if ambient.iter().any(|v|!v.is_finite()||*v<0.||*v>1e9){return Err("bounded ambient irradiance required".into());}let(m,n,ao)=self.evaluate(images,uv,n,t)?;let direct=shade(&m,p,n,eye,lights)?;Ok(std::array::from_fn(|j|direct[j]+ambient[j]*m.albedo[j]*(1.-m.metallic)*ao/std::f64::consts::PI))}
}
#[cfg(test)]mod tests{use super::*;fn surface()->Surface{Surface{albedo:[1.;3],metallic:1.,roughness:1.,base:None,metal_rough:None,occlusion:None,normal:None,ao_strength:1.,normal_scale:1.,double_sided:false}}
#[test]fn srgb_mr_channels_and_ao_strength(){let im=Image{width:1,height:1,rgba8:vec![128,64,192,255]};let slot=Slot{image:0,wrap_s:Wrap::Repeat,wrap_t:Wrap::Repeat,linear:true};let mut s=surface();s.base=Some(slot.clone());s.metal_rough=Some(slot.clone());s.occlusion=Some(slot);s.validate(&[im.clone()]).unwrap();let(m,_,ao)=s.evaluate(&[im],[0.5;2],[0.,0.,1.],[1.,0.,0.,1.]).unwrap();assert!((m.albedo[0]-linear(128./255.)).abs()<1e-12);assert_eq!(m.metallic,192./255.);assert_eq!(m.roughness,64./255.);assert_eq!(ao,128./255.);}
#[test]fn wraps_and_decode_before_bilinear(){let im=Image{width:2,height:1,rgba8:vec![0,0,0,255,255,255,255,255]};let s=Slot{image:0,wrap_s:Wrap::Repeat,wrap_t:Wrap::Clamp,linear:true};assert_eq!(sample(&s,&[im.clone()],[0.5,0.5],true).unwrap()[0],0.5);assert_eq!(sample(&s,&[im.clone()],[1.25,0.5],true).unwrap()[0],0.);let mut mirror=s.clone();mirror.wrap_s=Wrap::Mirror;assert_eq!(sample(&mirror,&[im],[1.25,0.5],true).unwrap()[0],1.);}
#[test]fn ao_does_not_dark_direct(){let mut s=surface();s.metallic=0.;let im=Image{width:1,height:1,rgba8:vec![0,0,0,255]};let lights=[Light::Directional{travel_direction:[0.,0.,-1.],radiance:[1.;3]}];let a=s.shade(&[im.clone()],[0.5;2],[0.,0.,1.],[1.,0.,0.,1.],[0.;3],[0.,0.,2.],&lights,[0.;3]).unwrap();s.occlusion=Some(Slot{image:0,wrap_s:Wrap::Clamp,wrap_t:Wrap::Clamp,linear:false});let b=s.shade(&[im],[0.5;2],[0.,0.,1.],[1.,0.,0.,1.],[0.;3],[0.,0.,2.],&lights,[0.;3]).unwrap();assert_eq!(a,b);}
}
